 */
K_THREAD_STACK_DEFINE(modem_pipe_event_work_q_stack, MODEM_PIPE_EVENT_WORK_Q_STACK_SIZE);
static struct k_work_q modem_pipe_event_work_q;

struct modem_pipe_event_work {
	struct k_work work;
	struct modem_pipe *pipe; /* Pointer to the pipe instance */
	enum modem_pipe_event event;
};

static struct modem_pipe_event_work work_items[MODEM_PIPE_WORK_ITEMS_MAX];

static struct modem_pipe_event_work *find_free_work_item(void) /* Removed pipe argument */
{
	for (size_t i = 0; i < MODEM_PIPE_WORK_ITEMS_MAX; ++i) {
		if (!k_work_is_pending(&work_items[i].work)) {
			return &work_items[i];
		}
	}

	return NULL;
}

static void modem_pipe_event_work_handler(struct k_work *item)
{
	struct modem_pipe_event_work *work = CONTAINER_OF(item, struct modem_pipe_event_work, work);
	struct modem_pipe *pipe = work->pipe; /* Corrected way to get pipe */

	if (pipe->api->event_handler != NULL) {
		pipe->api->event_handler(pipe, work->event, pipe->api->user_data);
	}
}

int modem_pipe_init(struct modem_pipe *pipe, const struct modem_pipe_api *api)
{
	__ASSERT_NO_MSG(pipe != NULL);
	__ASSERT_NO_MSG(api != NULL);

	memset(pipe, 0, sizeof(*pipe));
	pipe->api = api;
	k_mutex_init(&pipe->lock);

	for (size_t i = 0; i < MODEM_PIPE_WORK_ITEMS_MAX; ++i) {
		k_work_init(&work_items[i].work, modem_pipe_event_work_handler);
	}

	/* Start the dedicated event workqueue if not already started. */
	static bool work_q_started = false;
	if (!work_q_started) {
		k_work_queue_start(&modem_pipe_event_work_q, modem_pipe_event_work_q_stack,
				   K_THREAD_STACK_SIZEOF(modem_pipe_event_work_q_stack),
				   K_PRIO_PREEMPT(0), NULL);
		k_thread_name_set(&modem_pipe_event_work_q.thread, "modem_pipe_evt_wq");
		work_q_started = true;
	}

	return 0;
}

void modem_pipe_event_send(struct modem_pipe *pipe, enum modem_pipe_event event)
{
	struct modem_pipe_event_work *work;

	k_mutex_lock(&pipe->lock, K_FOREVER);

	// Find free work item
	work = find_free_work_item(); /* Removed pipe argument */
	if (work == NULL) {
		LOG_ERR("No free work items");
		k_mutex_unlock(&pipe->lock);
		return;
	}

	work->pipe = pipe; /* Set the pipe pointer */
	work->event = event;
	k_work_submit_to_queue(&modem_pipe_event_work_q, &work->work); /* Submit to dedicated workqueue */
	k_mutex_unlock(&pipe->lock);
}

int modem_pipe_attach(struct modem_pipe *pipe, modem_pipe_event_handler_t handler, void *user_data)
{
	__ASSERT_NO_MSG(pipe != NULL);

	k_mutex_lock(&pipe->lock, K_FOREVER);
	pipe->api->event_handler = handler;
	pipe->api->user_data = user_data;
	k_mutex_unlock(&pipe->lock);

	return 0;
}
